mapper.insert:
INSERT INTO `meetingPost` ( `userId`, `title`, `location`, `locationpoint`, `restLocation`, `expiredAt`, `contentText`, `afterMeetingContent`, `exerciseType`, `distance`, `speed`, `power`, `minHeadCount`, `maxHeadCount`, `isRestExist`, `isAbandonOkay`, `isAfterPartyExist`, `isLocationConnectedToKakao`, `isUserAbilityConnectedToStrava`, `isMyPaceShown`, `isMyFtpShown`, `currentStatus`, `createdAt`, `updatedAt`, `duration`, `height` )
VALUES ( #{userId}, #{title}, #{location}, ST_GeomFromText(CONCAT('POINT(', #{latitude}, ' ', #{longitude}, ')'), 4326), #{restLocation}, #{expiredAt}, #{contentText}, #{afterMeetingContent}, #{exerciseType}, #{distance}, #{speed}, #{power}, #{minHeadCount}, #{maxHeadCount}, #{isRestExist}, #{isAbandonOkay}, #{isAfterPartyExist}, #{isLocationConnectedToKakao}, #{isUserAbilityConnectedToStrava}, #{isMyPaceShown}, #{isMyFtpShown}, #{currentStatus}, NOW(), NOW(), #{duration}, #{height}
)

mapper.select:
SELECT `id`, `title`, `location`, `expiredAt`, `exerciseType`, `distance`, `speed`, `power`, `minHeadCount`, `maxHeadCount`, `isRestExist`, `isAbandonOkay`, `createdAt` FROM `meetingPost` WHERE `id` IN
#{id}
ORDER BY FIELD(`id`,
#{id}
)
